css:
.night-sky {
  width: 100%;
  height: 100%;
  background: linear-gradient(to top, #020111 0%, #0b0c28 100%);
  filter: url(#night-sky-filter);
  position: relative;
  overflow: hidden;
  pointer-events: none;
}

.stars {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(white 1px, transparent 1px),
    radial-gradient(#00ffaa 1px, transparent 1px),
    radial-gradient(#ffffff 1px, transparent 1px);
  background-size:
    3px 3px,
    4px 4px,
    5px 5px;
  background-position:
    0 0,
    100px 100px,
    200px 50px;
  animation: starTwinkle 5s infinite alternate ease-in-out;
  opacity: 0.06;
  z-index: 1;
}

.aurora-layer {
  position: absolute;
  inset: 0;
  background: radial-gradient(
      ellipse at 50% 80%,
      rgba(0, 255, 255, 0.05),
      transparent 70%
    ),
    radial-gradient(
      ellipse at 30% 90%,
      rgba(0, 150, 255, 0.07),
      transparent 80%
    );
  animation: auroraMove 20s ease-in-out infinite;
  background-size: 200% 200%;
  z-index: 2;
}
